package com.aditya.chat.service; import com.aditya.chat.dto.*; import com.aditya.chat.entity.AppUser; import com.aditya.chat.repository.UserRepository; import com.aditya.chat.security.JwtService; import org.springframework.http.HttpStatus; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.web.server.ResponseStatusException; @Service public class AuthService{final UserRepository users;final PasswordEncoder enc;final JwtService jwt;public AuthService(UserRepository u,PasswordEncoder e,JwtService j){users=u;enc=e;jwt=j;}public AuthResponse register(RegisterRequest r){if(users.existsByUsername(r.username()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Username already exists");users.save(new AppUser(r.username(),enc.encode(r.password())));return new AuthResponse(jwt.generate(r.username()),r.username());}public AuthResponse login(LoginRequest r){AppUser u=users.findByUsername(r.username()).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid credentials"));if(!enc.matches(r.password(),u.getPassword()))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid credentials");return new AuthResponse(jwt.generate(u.getUsername()),u.getUsername());}}
